#!/usr/bin/env python3
# Sound patch source: writes src/data/sounds.json (every sound of the game as synthesis layers for AL.Audio).
# Run: python3 tools/art/sounds.py   then   node tools/measure-audio.js   and   node tools/level-audio.js
# "expect" = the intent of each sound (duration window in seconds, spectral centroid window in Hz), checked by measure-audio.
import json, os
S = {}
def O(w, f, g, a=0.004, d=0.1, r=0.05, **k):
    L = {"t": "osc", "w": w, "f": f, "g": g, "a": a, "d": d, "dur": k.pop("dur", d), "r": r}; L.update(k); return L
def N(g, a=0.002, d=0.1, r=0.05, flt=None, **k):
    L = {"t": "noise", "g": g, "a": a, "d": d, "dur": k.pop("dur", d), "r": r}
    if flt: L["flt"] = flt
    L.update(k); return L
def P(f, g, d=0.6, r=0.2, **k):
    L = {"t": "pluck", "f": f, "g": g, "a": 0.002, "d": d, "dur": d, "r": r}; L.update(k); return L
def snd(name, cat, dur, cen, layers=None, variants=None, **k):
    s = {"cat": cat, "expect": {"dur": dur, "centroid": cen}}
    if variants: s["variants"] = variants
    else: s["layers"] = layers
    s.update(k); S[name] = s
bp = lambda f, q=1.0, *m: ["bandpass", f, q] + ([list(map(list, m))] if m else [])
lp = lambda f, q=0.7, *m: ["lowpass", f, q] + ([list(map(list, m))] if m else [])
hp = lambda f, q=0.7, *m: ["highpass", f, q] + ([list(map(list, m))] if m else [])
