def voice(f0, f1, d, g=0.3, wave="sawtooth", bf=900, q=2.5, vib=None, trem=None, a=0.03, at=0):
    L = O(wave, [f0, f1, d], g, a, d, d * 0.3, flt=bp(bf, q))
    if vib: L["vib"] = vib
    if trem: L["trem"] = trem
    if at: L["at"] = at
    return L
